//! WebP VP8L lossless subset tests (R147).
//!
//! The simple-code fixtures are generated by `tests/fixtures/generate_webp.py` and validated
//! with PIL/libwebp; the expected ARGB->RGBA output is stored as `.rgba` raw bytes so the
//! Rust decoder is checked byte-for-byte against an independent decoder.

use std::path::Path;

use image::{ImageError, ImageFormat, decode, detect_format};

fn fixture(relative: &str) -> Vec<u8> {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/webp")
        .join(relative);
    std::fs::read(&path).unwrap_or_else(|error| panic!("fixture {}: {error}", path.display()))
}

#[test]
fn detects_webp_container() {
    assert_eq!(
        detect_format(&fixture("v8l_two_color.webp")),
        ImageFormat::WebP
    );
}

#[test]
fn decodes_vp8l_two_colour_fixture_exactly() {
    let image = decode(&fixture("v8l_two_color.webp")).expect("VP8L");
    assert_eq!(image.dimensions(), (8, 8));
    assert_eq!(image.data, fixture("v8l_two_color.rgba"));
    assert_eq!(image.pixel(0, 0), Some([255, 0, 0, 255]));
    assert_eq!(image.pixel(7, 7), Some([0, 0, 255, 255]));
}

#[test]
fn decodes_vp8l_alpha_fixture_exactly() {
    let image = decode(&fixture("v8l_alpha.webp")).expect("VP8L alpha");
    assert_eq!(image.dimensions(), (8, 8));
    assert_eq!(image.data, fixture("v8l_alpha.rgba"));
    assert_eq!(image.pixel(0, 0), Some([255, 0, 0, 255]));
    assert_eq!(image.pixel(7, 7), Some([0, 0, 255, 0]), "transparent half");
}

#[test]
fn vp8l_transforms_outside_the_subset_are_typed_errors() {
    // PIL/libwebp encodes a solid colour with the colour-indexing transform.
    let error = decode(&fixture("palette_transform.webp")).expect_err("palette transform");
    match error {
        ImageError::UnsupportedFeature { feature } => {
            assert!(feature.contains("transform"), "{feature}");
        }
        other => panic!("expected UnsupportedFeature, got {other:?}"),
    }
}

#[test]
fn vp8_lossy_is_a_clear_unsupported_feature() {
    let error = decode(&fixture("lossy.webp")).expect_err("VP8 lossy");
    match error {
        ImageError::UnsupportedFeature { feature } => {
            assert!(feature.contains("lossy"), "{feature}");
        }
        other => panic!("expected UnsupportedFeature, got {other:?}"),
    }
}

#[test]
fn vp8l_dimension_limit_is_enforced_before_allocation() {
    let limits = image::PngLimits {
        max_dimension: 4,
        ..image::PngLimits::default()
    };
    let error = image::decode_with_limits(&fixture("v8l_two_color.webp"), &limits)
        .expect_err("dimension limit");
    assert!(
        matches!(error, ImageError::LimitExceeded { .. }),
        "unexpected error: {error:?}"
    );
}

#[test]
fn truncated_webp_is_a_typed_error_without_panic() {
    let bytes = fixture("v8l_two_color.webp");
    for length in [0, 4, 12, 20] {
        let error = decode(&bytes[..length]).expect_err("truncated WebP");
        assert!(
            matches!(
                error,
                ImageError::Truncated { .. }
                    | ImageError::InvalidData { .. }
                    | ImageError::InvalidSignature
            ),
            "length {length}: {error:?}"
        );
    }
}
